/* ===== 语言切换 ===== */
document.getElementById("langToggle").addEventListener("click", function () {
  LANG = LANG === "en" ? "zh" : "en";
  try { localStorage.setItem("qfr_lang", LANG); } catch (e) {}
  applyLang();
});
